        var sg = IAC.make(sys, "aws_security_group", { name: "web-staging", description: "Web servers", vpc_id: v.id, ingress: [{ description: "HTTP", from_port: 80, to_port: 80, protocol: "tcp", cidr_blocks: ["0.0.0.0/0"], ipv6_cidr_blocks: [], prefix_list_ids: [], security_groups: [], self: false }], egress: [] });
